import{_ as a,o as i,c as t,ae as r}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Specifications","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/02_SPECIFICATIONS.md","filePath":"sessions/20260226-helios-market-research/02_SPECIFICATIONS.md"}'),o={name:"sessions/20260226-helios-market-research/02_SPECIFICATIONS.md"};function n(l,e,s,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h1><h2 id="product-definition" tabindex="-1">Product Definition <a class="header-anchor" href="#product-definition" aria-label="Permalink to &quot;Product Definition&quot;">​</a></h2><p>HeliosApp is a terminal-first desktop IDE focused on high-concurrency terminal workloads with integrated AI execution control.</p><h2 id="product-lock-this-track" tabindex="-1">Product Lock (This Track) <a class="header-anchor" href="#product-lock-this-track" aria-label="Permalink to &quot;Product Lock (This Track)&quot;">​</a></h2><ul><li>Language strategy: <code>TS7-native</code> wherever possible</li><li>Package strategy: latest <code>beta</code>/<code>rc</code> channels by default with explicit rollback pins</li><li>Desktop shell: <code>ElectroBun</code></li><li>Renderers: <code>ghostty</code> and <code>rio</code> both supported behind feature flag</li><li>Worktree/task orchestrator: <code>par</code> required</li><li>Mux core: <code>zellij</code></li><li>Session durability and collaboration: <code>zmx</code> + <code>upterm</code> + <code>tmate</code> required (not optional)</li><li>Protocol stack: <code>ACP</code> (Agent Client Protocol) + <code>MCP</code> + <code>A2A</code> + internal local control bus</li></ul><h2 id="renderer-switching-requirement" tabindex="-1">Renderer Switching Requirement <a class="header-anchor" href="#renderer-switching-requirement" aria-label="Permalink to &quot;Renderer Switching Requirement&quot;">​</a></h2><ul><li>Settings must expose <code>renderer_engine</code> with values: <code>ghostty</code> or <code>rio</code>.</li><li>On settings change, app attempts hot renderer swap.</li><li>If hot swap is unsupported or unsafe, app must request and perform fast session-preserving restart.</li></ul><h2 id="prd" tabindex="-1">PRD <a class="header-anchor" href="#prd" aria-label="Permalink to &quot;PRD&quot;">​</a></h2><h3 id="product-objective" tabindex="-1">Product Objective <a class="header-anchor" href="#product-objective" aria-label="Permalink to &quot;Product Objective&quot;">​</a></h3><p>Ship a desktop app that feels as polished as modern GUI tools but preserves terminal-native speed and low overhead under heavy concurrency.</p><h3 id="success-metrics-v1" tabindex="-1">Success Metrics (v1) <a class="header-anchor" href="#success-metrics-v1" aria-label="Permalink to &quot;Success Metrics (v1)&quot;">​</a></h3><ul><li>Support 25 concurrent terminals across tabs/projects with no hard UI lockups.</li><li>Maintain median command input-to-render latency under 60 ms on target hardware.</li><li>Keep steady-state memory under 500 MB for typical workload profile.</li><li>Achieve &gt;80% user-reported trust in command explainability and rollback controls.</li></ul><h3 id="in-scope" tabindex="-1">In Scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to &quot;In Scope&quot;">​</a></h3><ul><li>Multi-project workspace model.</li><li>Terminal mux interface with split panes/tabs/session restore.</li><li>New project action: init local repo or clone remote repo to configurable path.</li><li>New chat action: choose provider/client profile.</li><li>Freehand terminal always available (raw terminal mode).</li><li>AI task mode with approval policies, diff previews, and rollback.</li><li>Session/audit logs per workspace.</li><li>Integrated share/handoff mode via <code>upterm</code> and <code>tmate</code>.</li><li>Worktree swarm task routing via <code>par</code>.</li></ul><h3 id="out-of-scope-v1" tabindex="-1">Out of Scope (v1) <a class="header-anchor" href="#out-of-scope-v1" aria-label="Permalink to &quot;Out of Scope (v1)&quot;">​</a></h3><ul><li>Full visual code editor parity with VS Code.</li><li>Cloud multi-tenant control plane.</li><li>Full enterprise IAM suite.</li></ul><h2 id="functional-requirements-fr" tabindex="-1">Functional Requirements (FR) <a class="header-anchor" href="#functional-requirements-fr" aria-label="Permalink to &quot;Functional Requirements (FR)&quot;">​</a></h2><ul><li>FR-1 Workspace creation/open/close with persistent metadata.</li><li>FR-2 Project bootstrap from local path, git init, or git clone.</li><li>FR-3 Terminal session manager supports &gt;=25 live sessions.</li><li>FR-4 Multiplexing UI supports tabs, splits, detached/re-attachable sessions.</li><li>FR-5 AI provider profile selector at chat/session creation.</li><li>FR-6 Freehand terminal mode can run without AI mediation.</li><li>FR-7 AI mode supports plan/apply/approval workflow.</li><li>FR-8 Command policy layer (allowlist/denylist + sensitive path protection).</li><li>FR-9 Session replay and searchable audit logs.</li><li>FR-10 Crash recovery restores project and terminal state.</li><li>FR-11 Renderer engine feature flag and safe runtime swap/restart behavior.</li><li>FR-12 Shared session handoff flow using <code>upterm</code> and <code>tmate</code> from active terminals.</li><li>FR-13 <code>zmx</code> lifecycle integration for durable terminal process persistence.</li><li>FR-14 <code>par</code> integration to create/manage agent lanes as worktree-backed tasks.</li><li>FR-15 ACP-compatible client runtime boundary for agent orchestration adapters.</li></ul><h2 id="non-functional-requirements-nfr" tabindex="-1">Non-Functional Requirements (NFR) <a class="header-anchor" href="#non-functional-requirements-nfr" aria-label="Permalink to &quot;Non-Functional Requirements (NFR)&quot;">​</a></h2><ul><li>NFR-1 Memory budget target under 500 MB typical.</li><li>NFR-2 App startup to interactive state under 2 seconds on reference machine.</li><li>NFR-3 No command execution without explicit policy path.</li><li>NFR-4 Provider isolation prevents credential/session cross-leakage.</li><li>NFR-5 UI remains responsive under high terminal output throughput.</li><li>NFR-6 Renderer switch operation must complete within 3 seconds (hot swap) or 8 seconds (restart path).</li></ul><h2 id="user-stories" tabindex="-1">User Stories <a class="header-anchor" href="#user-stories" aria-label="Permalink to &quot;User Stories&quot;">​</a></h2><ul><li>US-1 As a platform engineer, I can open 20+ terminals across 3 repos and keep them responsive.</li><li>US-2 As a backend developer, I can start a new repo from a URL and immediately run tasks in AI or freehand mode.</li><li>US-3 As a security lead, I can enforce blocked commands and protected paths globally.</li><li>US-4 As a power user, I can switch model clients without rebuilding my workspace.</li><li>US-5 As a team lead, I can inspect audit logs for what command ran, why, and what changed.</li><li>US-6 As an operator, I can switch between <code>ghostty</code> and <code>rio</code> from settings and continue working with minimal interruption.</li><li>US-7 As an on-call engineer, I can share active terminal context through <code>upterm</code> or <code>tmate</code> without losing session continuity.</li><li>US-8 As a swarm operator, I can dispatch tasks into dedicated worktrees via <code>par</code> and attach to each lane quickly.</li></ul><h2 id="adrs" tabindex="-1">ADRs <a class="header-anchor" href="#adrs" aria-label="Permalink to &quot;ADRs&quot;">​</a></h2><h3 id="adr-001-desktop-runtime" tabindex="-1">ADR-001: Desktop Runtime <a class="header-anchor" href="#adr-001-desktop-runtime" aria-label="Permalink to &quot;ADR-001: Desktop Runtime&quot;">​</a></h3><p>Decision: Use <code>ElectroBun</code> as the desktop shell. Rationale: Maximum innovation and runtime performance experimentation is explicitly prioritized over maturity risk.</p><h3 id="adr-002-terminal-engine" tabindex="-1">ADR-002: Terminal Engine <a class="header-anchor" href="#adr-002-terminal-engine" aria-label="Permalink to &quot;ADR-002: Terminal Engine&quot;">​</a></h3><p>Decision: Implement dual-engine rendering (<code>ghostty</code> and <code>rio</code>) with feature flag and runtime switch semantics. Rationale: Preserve both high-confidence and high-upside renderer tracks while keeping one product surface.</p><h3 id="adr-003-worktree-and-mux-backend" tabindex="-1">ADR-003: Worktree and Mux Backend <a class="header-anchor" href="#adr-003-worktree-and-mux-backend" aria-label="Permalink to &quot;ADR-003: Worktree and Mux Backend&quot;">​</a></h3><p>Decision: Use <code>par</code> for worktree/task orchestration and <code>zellij</code> as mux core. Rationale: Worktree-aware swarm execution is a first-class requirement and should be separate from pane/tab runtime.</p><h3 id="adr-004-session-durability-and-handoff" tabindex="-1">ADR-004: Session Durability and Handoff <a class="header-anchor" href="#adr-004-session-durability-and-handoff" aria-label="Permalink to &quot;ADR-004: Session Durability and Handoff&quot;">​</a></h3><p>Decision: Require <code>zmx</code>, <code>upterm</code>, and <code>tmate</code> integrations. Rationale: Persistent agent sessions and human handoff are mandatory operational requirements.</p><h3 id="adr-005-ai-and-interop-protocols" tabindex="-1">ADR-005: AI and Interop Protocols <a class="header-anchor" href="#adr-005-ai-and-interop-protocols" aria-label="Permalink to &quot;ADR-005: AI and Interop Protocols&quot;">​</a></h3><p>Decision: Use ACP at client boundary, MCP for tools, A2A for external federation, and internal local control bus for deterministic runtime orchestration. Rationale: Separation of concerns keeps local performance deterministic while preserving interop.</p><h2 id="arus" tabindex="-1">ARUs <a class="header-anchor" href="#arus" aria-label="Permalink to &quot;ARUs&quot;">​</a></h2><h3 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h3><ul><li>Dual-renderer model can be maintained without unacceptable engineering drag.</li><li><code>ElectroBun</code> provides sufficient native control and stability for v1 targets.</li></ul><h3 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h3><ul><li>Dual renderer support doubles compatibility testing surface.</li><li>Cross-platform differences in renderer integration may impact hot-swap behavior.</li><li>Collaboration layers can increase attack surface if not tightly gated.</li><li>Worktree churn can create filesystem and cleanup complexity under high swarm volume.</li></ul><h3 id="uncertainties" tabindex="-1">Uncertainties <a class="header-anchor" href="#uncertainties" aria-label="Permalink to &quot;Uncertainties&quot;">​</a></h3><ul><li>Final API stability velocity of <code>ElectroBun</code> and <code>rio</code> on required platform matrix.</li><li>Operational limits under sustained 25-terminal + share-session concurrency.</li></ul>',40)])])}const m=a(o,[["render",n]]);export{p as __pageData,m as default};
